-- ============================================================================
-- B5 FOLLOW-ON W3 (Suite Full precision): uncertainty capstone brief.
--
-- Plan of record: docs/graded-field-audit/FOLLOW-ON-PROGRAMME.md section 2 and
-- the section 1 Suite rows, decision D3 (owner approved D1 to D7 as
-- recommended, 2026-09-21). The Suite app the capstone is read in gains a
-- "Full precision" switch, off by default, that prints the graded quantities
-- at the precision they are graded to. The brief now says to switch it on.
--
-- BEGINNER
--   Fields read with the switch on: um_y5_royalty_musd, um_y4_tax_musd,
--   um_y11_ncf_musd, um_payback_year_cum_ncf_musd, um_npv_musd,
--   um_npv_price_up_30_musd.
--   The cards and cashflow print compact money ("$45M") that cannot carry a
--   0.001 $MM tolerance; the tornado prints 1 decimal.
--   APPENDED: Read the figures in the NPV Scenario Builder with its Full
--   precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- INTERMEDIATE
--   Fields read with the switch on: um_breakeven_10th_percentile_usd_bbl,
--   um_breakeven_90th_percentile_usd_bbl, um_tornado_capex_high_side_usd_bbl.
--   The summary cards print 2 decimals and the tornado tooltip 2; the prompt
--   asks 4.
--   APPENDED: Read the figures in the Probabilistic Breakeven Analyzer with its
--   Full precision switch on (at the top of the page): it prints them to the
--   precision this capstone grades, with no digit grouping.
--
-- ADVANCED
--   Fields read with the switch on: um_mc_low_case_p90_npv_musd,
--   um_mc_high_case_p10_npv_musd, um_mc_emv_musd,
--   um_mc_10th_percentile_floor_rule_musd,
--   um_breakeven_median_next_seed_usd_bbl.
--   The Builder hard-coded 1000 iterations, 20 percent ranges and its default
--   seed, so the stated Monte Carlo could not be run, and the sample was never
--   shown or exported; the cards print compact money.
--   APPENDED: Read the figures in the NPV Scenario Builder and the Probabilistic
--   Breakeven Analyzer with their Full precision switch on (at the top of each
--   page): they print them to the precision this capstone grades, with no digit
--   grouping. With it on, the Builder's Risk tab shows the Monte Carlo settings
--   (iterations, the three ranges and the seed) and an Export sorted sample
--   button, a CSV of every NPV in rank order.
--
-- WHAT DOES NOT MOVE. `fields` (every key, label, unit, expected and
-- tolerance, and their order), title, dataset, status and the row. The guard
-- requires `fields` to equal its post-W1 value exactly, before and after, so
-- no answer grades differently and no attempts guard is needed.
--
-- ORDER. Apply only once the Suite build carrying the W3 switch is live (the
-- brief names it). Runs after W1 (20261024*): refuses without it.
--
-- GUARDS. Each prompt must hold its post-W1 text (md5, rewritten) or its W3
-- text (left alone), with the exact fields. Anything else raises and the file
-- rolls back. Generated by docs/graded-field-audit/w3_capstones.py from
-- w3/uncertainty.json. SAFE TO RE-RUN: a second run writes nothing.
-- ============================================================================

do $$
declare
  v_n        integer;
  v_count    integer;
  v_written  integer := 0;
  v_s0       text;
  v_s1       text;
  v_s2       text;
begin
  -- uncertainty / beginner
  select count(*) into v_n from public.academy_capstones where app_slug = 'uncertainty' and tier = 'beginner' and active;
  if v_n <> 1 then raise exception 'w3 uncertainty refused: uncertainty/beginner has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'bc1e3477352465a5dba99280bdcfca84' and fields = '[{"key": "um_y5_royalty_musd", "tol": 0.001, "unit": "million USD", "label": "Royalty in year 5 (2032)", "expected": 10.460333519999999}, {"key": "um_y4_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Tax in year 4 (2031)", "expected": 14.305144251000002}, {"key": "um_y11_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Net cash flow in year 11 (2038)", "expected": 10.484178912667886}, {"key": "um_payback_year_cum_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Cumulative net cash flow at the end of the year in which payback completes", "expected": 19.68181128809999}, {"key": "um_npv_musd", "tol": 0.001, "unit": "million USD", "label": "NPV, mid-year discounting at the case rate", "expected": 45.46305836029683}, {"key": "um_npv_price_up_30_musd", "tol": 0.001, "unit": "million USD", "label": "NPV with the oil price scaled by 1.3 (the sensitivity sweep high end)", "expected": 123.87393222150361}]'::jsonb then 'old'
              when md5(prompt) = 'adcd55315ed32b15c7d7a81d70f3f280' and fields = '[{"key": "um_y5_royalty_musd", "tol": 0.001, "unit": "million USD", "label": "Royalty in year 5 (2032)", "expected": 10.460333519999999}, {"key": "um_y4_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Tax in year 4 (2031)", "expected": 14.305144251000002}, {"key": "um_y11_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Net cash flow in year 11 (2038)", "expected": 10.484178912667886}, {"key": "um_payback_year_cum_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Cumulative net cash flow at the end of the year in which payback completes", "expected": 19.68181128809999}, {"key": "um_npv_musd", "tol": 0.001, "unit": "million USD", "label": "NPV, mid-year discounting at the case rate", "expected": 45.46305836029683}, {"key": "um_npv_price_up_30_musd", "tol": 0.001, "unit": "million USD", "label": "NPV with the oil price scaled by 1.3 (the sensitivity sweep high end)", "expected": 123.87393222150361}]'::jsonb then 'new'
              else 'other' end
    into v_s0 from public.academy_capstones where app_slug = 'uncertainty' and tier = 'beginner' and active;
  if v_s0 = 'other' then
    raise exception 'w3 uncertainty refused: uncertainty/beginner matches neither its post-W1 form (prompt md5 bc1e3477352465a5dba99280bdcfca84) nor its W3 form (prompt md5 adcd55315ed32b15c7d7a81d70f3f280), with the fields this file was generated against';
  end if;

  -- uncertainty / intermediate
  select count(*) into v_n from public.academy_capstones where app_slug = 'uncertainty' and tier = 'intermediate' and active;
  if v_n <> 1 then raise exception 'w3 uncertainty refused: uncertainty/intermediate has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = 'ad690bf0e0ab05b2d00319e0a040c2d7' and fields = '[{"key": "um_capex_fit_max_musd", "tol": 0.001, "unit": "million USD", "label": "Maximum of the triangular fitted to the capex belief", "expected": 213.31559480312313}, {"key": "um_opex_fit_mode_musd", "tol": 0.001, "unit": "million USD", "label": "Mode of the triangular fitted to the opex belief", "expected": 14.693828529294601}, {"key": "um_base_breakeven_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Base case breakeven price at the stated medians", "expected": 68.03901813890326}, {"key": "um_breakeven_10th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "10th percentile of breakeven price", "expected": 58.94391930684155}, {"key": "um_breakeven_90th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "90th percentile of breakeven price", "expected": 81.53480911819321}, {"key": "um_tornado_capex_high_side_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Capex tornado bar, high side, measured from the base breakeven", "expected": 9.618411257207583}]'::jsonb then 'old'
              when md5(prompt) = 'd41a300ee9e9b9fce95cf08435a1b6e0' and fields = '[{"key": "um_capex_fit_max_musd", "tol": 0.001, "unit": "million USD", "label": "Maximum of the triangular fitted to the capex belief", "expected": 213.31559480312313}, {"key": "um_opex_fit_mode_musd", "tol": 0.001, "unit": "million USD", "label": "Mode of the triangular fitted to the opex belief", "expected": 14.693828529294601}, {"key": "um_base_breakeven_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Base case breakeven price at the stated medians", "expected": 68.03901813890326}, {"key": "um_breakeven_10th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "10th percentile of breakeven price", "expected": 58.94391930684155}, {"key": "um_breakeven_90th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "90th percentile of breakeven price", "expected": 81.53480911819321}, {"key": "um_tornado_capex_high_side_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Capex tornado bar, high side, measured from the base breakeven", "expected": 9.618411257207583}]'::jsonb then 'new'
              else 'other' end
    into v_s1 from public.academy_capstones where app_slug = 'uncertainty' and tier = 'intermediate' and active;
  if v_s1 = 'other' then
    raise exception 'w3 uncertainty refused: uncertainty/intermediate matches neither its post-W1 form (prompt md5 ad690bf0e0ab05b2d00319e0a040c2d7) nor its W3 form (prompt md5 d41a300ee9e9b9fce95cf08435a1b6e0), with the fields this file was generated against';
  end if;

  -- uncertainty / advanced
  select count(*) into v_n from public.academy_capstones where app_slug = 'uncertainty' and tier = 'advanced' and active;
  if v_n <> 1 then raise exception 'w3 uncertainty refused: uncertainty/advanced has % active capstone rows, expected 1', v_n; end if;
  select case when md5(prompt) = '72990ef81352b73d773d29f5c0ddfd73' and fields = '[{"key": "um_mc_low_case_p90_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: Low case P90 NPV", "expected": -9.458763830643502}, {"key": "um_mc_high_case_p10_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: High case P10 NPV", "expected": 103.72137834406172}, {"key": "um_mc_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: EMV", "expected": 44.907432365660654}, {"key": "um_mc_10th_percentile_floor_rule_musd", "tol": 0.001, "unit": "million USD", "label": "10th percentile of the Monte Carlo NPVs by the breakeven engine rule, sorted[floor(0.1 n)]", "expected": -9.443407561604305}, {"key": "um_breakeven_median_next_seed_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Median breakeven price when the same run is drawn with seed 9032", "expected": 69.53330617933949}, {"key": "um_breakeven_at_hurdle_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Breakeven price to a 100 million USD NPV hurdle at the stated medians", "expected": 97.3773177308266}]'::jsonb then 'old'
              when md5(prompt) = 'ffb85cde6413f1e01069ee3f8d69bddd' and fields = '[{"key": "um_mc_low_case_p90_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: Low case P90 NPV", "expected": -9.458763830643502}, {"key": "um_mc_high_case_p10_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: High case P10 NPV", "expected": 103.72137834406172}, {"key": "um_mc_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: EMV", "expected": 44.907432365660654}, {"key": "um_mc_10th_percentile_floor_rule_musd", "tol": 0.001, "unit": "million USD", "label": "10th percentile of the Monte Carlo NPVs by the breakeven engine rule, sorted[floor(0.1 n)]", "expected": -9.443407561604305}, {"key": "um_breakeven_median_next_seed_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Median breakeven price when the same run is drawn with seed 9032", "expected": 69.53330617933949}, {"key": "um_breakeven_at_hurdle_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Breakeven price to a 100 million USD NPV hurdle at the stated medians", "expected": 97.3773177308266}]'::jsonb then 'new'
              else 'other' end
    into v_s2 from public.academy_capstones where app_slug = 'uncertainty' and tier = 'advanced' and active;
  if v_s2 = 'other' then
    raise exception 'w3 uncertainty refused: uncertainty/advanced matches neither its post-W1 form (prompt md5 72990ef81352b73d773d29f5c0ddfd73) nor its W3 form (prompt md5 ffb85cde6413f1e01069ee3f8d69bddd), with the fields this file was generated against';
  end if;

  -- nothing to write: every row is already in its W3 form
  if v_s0 = 'new' and v_s1 = 'new' and v_s2 = 'new' then
    raise notice 'w3 uncertainty: 0 of 3 row(s) written, all already applied';
    return;
  end if;

  -- W1 (20261024*) must be applied first: its rows are this file's base
  if not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'seismolord' and c.tier = 'intermediate' and c.active and f->>'key' = 'corr_zero_lag')
     or not exists (select 1 from public.academy_capstones c, lateral jsonb_array_elements(c.fields) f
                  where c.app_slug = 'mbal' and c.tier = 'beginner' and c.active and f->>'key' = 'eo_last_rb_stb')
     or not exists (select 1 from public.academy_capstones
                  where app_slug = 'basin' and tier = 'beginner' and active and prompt like 'Open book%') then
    raise exception 'w3 uncertainty refused: W1 (20261024*) is not applied on this database; apply it first (/root/w1-apply/apply.sh apply --prod)';
  end if;

  if v_s0 = 'old' then
    update public.academy_capstones
       set prompt = 'The UMUNEDE case, entered in the NPV Scenario Builder''s quick form: oil 3900 bopd declining 10 percent a year from 2028, oil price 64 USD per bbl, capex 150 million USD split evenly over the first two years, fixed opex 2.1 million USD a year, variable opex 14.5 USD per bbl, royalty 17.5 percent, tax 38 percent, discount rate 13 percent. The quick form builds a 20 year case; years below count from 2028 as year 1. Read six values from the case and its sensitivity sweep. Money to four decimals in million USD. Read the figures in the NPV Scenario Builder with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'uncertainty' and tier = 'beginner' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 uncertainty refused: uncertainty/beginner updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'adcd55315ed32b15c7d7a81d70f3f280' and fields = '[{"key": "um_y5_royalty_musd", "tol": 0.001, "unit": "million USD", "label": "Royalty in year 5 (2032)", "expected": 10.460333519999999}, {"key": "um_y4_tax_musd", "tol": 0.001, "unit": "million USD", "label": "Tax in year 4 (2031)", "expected": 14.305144251000002}, {"key": "um_y11_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Net cash flow in year 11 (2038)", "expected": 10.484178912667886}, {"key": "um_payback_year_cum_ncf_musd", "tol": 0.001, "unit": "million USD", "label": "Cumulative net cash flow at the end of the year in which payback completes", "expected": 19.68181128809999}, {"key": "um_npv_musd", "tol": 0.001, "unit": "million USD", "label": "NPV, mid-year discounting at the case rate", "expected": 45.46305836029683}, {"key": "um_npv_price_up_30_musd", "tol": 0.001, "unit": "million USD", "label": "NPV with the oil price scaled by 1.3 (the sensitivity sweep high end)", "expected": 123.87393222150361}]'::jsonb) from public.academy_capstones where app_slug = 'uncertainty' and tier = 'beginner' and active) is not true then
    raise exception 'w3 uncertainty refused: uncertainty/beginner does not read back as its W3 form';
  end if;

  if v_s1 = 'old' then
    update public.academy_capstones
       set prompt = 'The UMUNEDE case, entered in the NPV Scenario Builder''s quick form: oil 3900 bopd declining 10 percent a year from 2028, oil price 64 USD per bbl, capex 150 million USD split evenly over the first two years, fixed opex 2.1 million USD a year, variable opex 14.5 USD per bbl, royalty 17.5 percent, tax 38 percent, discount rate 13 percent. The quick form builds a 20 year case; years below count from 2028 as year 1. In the Probabilistic Breakeven Analyzer on UMUNEDE''s own 20 year oil profile from that case, at the same royalty, tax and discount rate and a target NPV of 0: capex beliefs 125 / 150 / 185 million USD, opex 14 / 17.5 / 23 million USD a year and production efficiency 84 / 90 / 95 percent, each as its 10th, 50th and 90th percentile; 4000 iterations at seed 9031. Read six values from the fits, the base case, the sample and the tornado. Prices to four decimals in USD per bbl, money in million USD. Read the figures in the Probabilistic Breakeven Analyzer with its Full precision switch on (at the top of the page): it prints them to the precision this capstone grades, with no digit grouping.'
     where app_slug = 'uncertainty' and tier = 'intermediate' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 uncertainty refused: uncertainty/intermediate updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'd41a300ee9e9b9fce95cf08435a1b6e0' and fields = '[{"key": "um_capex_fit_max_musd", "tol": 0.001, "unit": "million USD", "label": "Maximum of the triangular fitted to the capex belief", "expected": 213.31559480312313}, {"key": "um_opex_fit_mode_musd", "tol": 0.001, "unit": "million USD", "label": "Mode of the triangular fitted to the opex belief", "expected": 14.693828529294601}, {"key": "um_base_breakeven_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Base case breakeven price at the stated medians", "expected": 68.03901813890326}, {"key": "um_breakeven_10th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "10th percentile of breakeven price", "expected": 58.94391930684155}, {"key": "um_breakeven_90th_percentile_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "90th percentile of breakeven price", "expected": 81.53480911819321}, {"key": "um_tornado_capex_high_side_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Capex tornado bar, high side, measured from the base breakeven", "expected": 9.618411257207583}]'::jsonb) from public.academy_capstones where app_slug = 'uncertainty' and tier = 'intermediate' and active) is not true then
    raise exception 'w3 uncertainty refused: uncertainty/intermediate does not read back as its W3 form';
  end if;

  if v_s2 = 'old' then
    update public.academy_capstones
       set prompt = 'The UMUNEDE case, entered in the NPV Scenario Builder''s quick form: oil 3900 bopd declining 10 percent a year from 2028, oil price 64 USD per bbl, capex 150 million USD split evenly over the first two years, fixed opex 2.1 million USD a year, variable opex 14.5 USD per bbl, royalty 17.5 percent, tax 38 percent, discount rate 13 percent. The quick form builds a 20 year case; years below count from 2028 as year 1. In the Probabilistic Breakeven Analyzer on UMUNEDE''s own 20 year oil profile from that case, at the same royalty, tax and discount rate and a target NPV of 0: capex beliefs 125 / 150 / 185 million USD, opex 14 / 17.5 / 23 million USD a year and production efficiency 84 / 90 / 95 percent, each as its 10th, 50th and 90th percentile; 4000 iterations at seed 9031. The Scenario Builder''s Monte Carlo on the UMUNEDE case: 1200 iterations, price uncertainty plus or minus 22 percent, capex 15 percent and reserves 20 percent, seed 9031. An NPV takes P-labels under the exceedance meaning (P90 is the Low case); a breakeven price takes percentiles. Read six values. Read the figures in the NPV Scenario Builder and the Probabilistic Breakeven Analyzer with their Full precision switch on (at the top of each page): they print them to the precision this capstone grades, with no digit grouping. With it on, the Builder''s Risk tab shows the Monte Carlo settings (iterations, the three ranges and the seed) and an Export sorted sample button, a CSV of every NPV in rank order.'
     where app_slug = 'uncertainty' and tier = 'advanced' and active;
    get diagnostics v_count = row_count;
    if v_count <> 1 then raise exception 'w3 uncertainty refused: uncertainty/advanced updated % rows', v_count; end if;
    v_written := v_written + 1;
  end if;
  if (select (md5(prompt) = 'ffb85cde6413f1e01069ee3f8d69bddd' and fields = '[{"key": "um_mc_low_case_p90_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: Low case P90 NPV", "expected": -9.458763830643502}, {"key": "um_mc_high_case_p10_npv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: High case P10 NPV", "expected": 103.72137834406172}, {"key": "um_mc_emv_musd", "tol": 0.001, "unit": "million USD", "label": "Scenario Builder Monte Carlo: EMV", "expected": 44.907432365660654}, {"key": "um_mc_10th_percentile_floor_rule_musd", "tol": 0.001, "unit": "million USD", "label": "10th percentile of the Monte Carlo NPVs by the breakeven engine rule, sorted[floor(0.1 n)]", "expected": -9.443407561604305}, {"key": "um_breakeven_median_next_seed_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Median breakeven price when the same run is drawn with seed 9032", "expected": 69.53330617933949}, {"key": "um_breakeven_at_hurdle_usd_bbl", "tol": 0.001, "unit": "USD per bbl", "label": "Breakeven price to a 100 million USD NPV hurdle at the stated medians", "expected": 97.3773177308266}]'::jsonb) from public.academy_capstones where app_slug = 'uncertainty' and tier = 'advanced' and active) is not true then
    raise exception 'w3 uncertainty refused: uncertainty/advanced does not read back as its W3 form';
  end if;

  raise notice 'w3 uncertainty: % of 3 row(s) written, % already applied', v_written, 3 - v_written;
end $$;
